      const slots = t.loop ? t.loop.advertiser.count : 0;
      const perSlot = calc.perSlotPerDayPerDisplay(e.revenue, slots, displays, nDays);
      const capacityViews = (t.averageViewsRaw || 0) * slots * displays * nDays;
